/*
 * Application schema bootstrap for the local PostgreSQL database.
 * psql variables supplied by the container initializer:
 *   app_schema - schema used by the application (default: shared_expenses)
 *   app_user   - application database owner
 */

CREATE SCHEMA IF NOT EXISTS :"app_schema" AUTHORIZATION :"app_user";
SET search_path TO :"app_schema", public;

CREATE TABLE "APP_USERS" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "USERNAME" VARCHAR(255) NOT NULL,
    "EMAIL" VARCHAR(255) NOT NULL,
    "PASSWORD_HASH" VARCHAR(255) NOT NULL,
    "CREATED_AT" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "UQ_APP_USERS_USERNAME" UNIQUE ("USERNAME"),
    CONSTRAINT "UQ_APP_USERS_EMAIL" UNIQUE ("EMAIL")
);

CREATE TABLE "EXPENSE_GROUPS" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "NAME" VARCHAR(255) NOT NULL,
    "DELETED_AT" TIMESTAMP
);

CREATE TABLE "MEMBERSHIP" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "GROUP_ID" BIGINT NOT NULL,
    "USER_ID" BIGINT NOT NULL,
    "JOINED_AT" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "LEFT_AT" TIMESTAMP,
    CONSTRAINT "FK_MEMBERSHIP_GROUP"
        FOREIGN KEY ("GROUP_ID") REFERENCES "EXPENSE_GROUPS" ("ID"),
    CONSTRAINT "FK_MEMBERSHIP_USER"
        FOREIGN KEY ("USER_ID") REFERENCES "APP_USERS" ("ID"),
    CONSTRAINT "UQ_MEMBERSHIP_GROUP_USER" UNIQUE ("GROUP_ID", "USER_ID")
);

CREATE TABLE "EXPENSES" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "MEMBERSHIP_ID" BIGINT NOT NULL,
    "PAID_BY" BIGINT NOT NULL,
    "EXPENSE" NUMERIC(10, 2) NOT NULL,
    "CREATED_AT" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "DELETED_AT" TIMESTAMP,
    CONSTRAINT "FK_EXPENSES_MEMBERSHIP"
        FOREIGN KEY ("MEMBERSHIP_ID") REFERENCES "MEMBERSHIP" ("ID"),
    CONSTRAINT "FK_EXPENSES_PAID_BY"
        FOREIGN KEY ("PAID_BY") REFERENCES "MEMBERSHIP" ("ID"),
    CONSTRAINT "CHK_EXPENSES_AMOUNT_POSITIVE" CHECK ("EXPENSE" > 0)
);

CREATE TABLE "EXPENSE_PARTICIPANTS" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "MEMBERSHIP_ID" BIGINT NOT NULL,
    "EXPENSE_ID" BIGINT NOT NULL,
    "SHARED_EXPENSE" NUMERIC(10, 2) NOT NULL,
    CONSTRAINT "FK_EXPENSE_PARTICIPANTS_MEMBERSHIP"
        FOREIGN KEY ("MEMBERSHIP_ID") REFERENCES "MEMBERSHIP" ("ID"),
    CONSTRAINT "FK_EXPENSE_PARTICIPANTS_EXPENSE"
        FOREIGN KEY ("EXPENSE_ID") REFERENCES "EXPENSES" ("ID"),
    CONSTRAINT "UQ_EXPENSE_PARTICIPANTS_MEMBER_EXPENSE"
        UNIQUE ("MEMBERSHIP_ID", "EXPENSE_ID"),
    CONSTRAINT "CHK_SHARED_EXPENSE_POSITIVE" CHECK ("SHARED_EXPENSE" >= 0)
);

CREATE TABLE "EXPENSE_ACTIVITY_LOG" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "EXPENSE_ID" BIGINT NOT NULL,
    "MEMBERSHIP_ID" BIGINT NOT NULL,
    "ACTIVITY_TYPE" VARCHAR(100) NOT NULL,
    "OLD_VALUE" NUMERIC(10, 2),
    "MESSAGE" VARCHAR(255),
    "CREATED_AT" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "FK_EXPENSE_ACTIVITY_LOG_EXPENSE"
        FOREIGN KEY ("EXPENSE_ID") REFERENCES "EXPENSES" ("ID"),
    CONSTRAINT "FK_EXPENSE_ACTIVITY_LOG_MEMBERSHIP"
        FOREIGN KEY ("MEMBERSHIP_ID") REFERENCES "MEMBERSHIP" ("ID")
);

CREATE INDEX "IDX_MEMBERSHIP_USER" ON "MEMBERSHIP" ("USER_ID");
CREATE INDEX "IDX_EXPENSES_MEMBERSHIP" ON "EXPENSES" ("MEMBERSHIP_ID");
CREATE INDEX "IDX_EXPENSES_PAID_BY" ON "EXPENSES" ("PAID_BY");
CREATE INDEX "IDX_EXPENSE_PARTICIPANTS_EXPENSE"
    ON "EXPENSE_PARTICIPANTS" ("EXPENSE_ID");
CREATE INDEX "IDX_EXPENSE_ACTIVITY_LOG_EXPENSE"
    ON "EXPENSE_ACTIVITY_LOG" ("EXPENSE_ID");
CREATE INDEX "IDX_EXPENSE_ACTIVITY_LOG_MEMBERSHIP"
    ON "EXPENSE_ACTIVITY_LOG" ("MEMBERSHIP_ID");

COMMENT ON COLUMN "EXPENSES"."MEMBERSHIP_ID" IS
    'Membership that created or owns the expense record';
COMMENT ON COLUMN "EXPENSES"."PAID_BY" IS
    'Membership that paid the expense';
COMMENT ON COLUMN "EXPENSE_ACTIVITY_LOG"."MEMBERSHIP_ID" IS
    'Membership that performed the logged activity';
COMMENT ON COLUMN "EXPENSE_ACTIVITY_LOG"."OLD_VALUE" IS
    'Previous numeric value before the activity occurred';
